class Person {
  private int age;
  void setAge(int a) { if (a >= 0) age = a; }
  int getAge() { return age; }
}
class Main {
  public static void main(String[] args) {
    Person p = new Person();
    p.setAge(-5);
    p.setAge(30);
    System.out.println(p.getAge());
  }
}

